INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am4_l20_gp4','am4_l20','though 让步 + whenever',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am4_l20_gp5','am4_l20','as … as(同级比较)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am4_l20_gp6','am4_l20','词汇辨析(venom/prey/carnivore)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l20','sulfur','sulphur','硫;拼写差异,美语 sulfur') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l20','mustache','moustache','(嘴上的)胡子;拼写差异,美语 mustache') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l20','esophagus','oesophagus','食道;拼写差异,美语 esophagus') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l20','cozy','cosy','舒适的;拼写差异,美语 cozy') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l20','come about','',NULL,'/kʌm əˈbaʊt/','How it came about is a mystery.','这是怎么发生的,是个谜。','How did the accident come about?','这场事故是怎么发生的?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l20','live on','',NULL,'/lɪv ɑːn/','Snakes live on rats and mice.','蛇以老鼠为食。','Pandas live on bamboo.','熊猫以竹子为食。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l20','act on','',NULL,'/ækt ɑːn/','One poison acts on the nerves.','一种毒作用于神经。','The medicine acts on the stomach.','这药作用于胃部。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l20','cut both ways','',NULL,'/kʌt boʊθ weɪz/','Venom can cut both ways.','毒液可能是双刃的。','This rule cuts both ways.','这条规则是把双刃剑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp1','choice','{"stem":"\"___ snakes came to make venom is still a mystery.\"(疑问词引导主语从句,‘…是如何’,填连词)","options":["How","Which","What","That"],"answer_index":0,"stem_cn":"蛇是如何造出毒液的,至今仍是个谜。","explanation_cn":"疑问词从句作全句开头,‘…是如何’用 How;整句谓语用 is。✓ How snakes came to make venom is a mystery. ✗ That(不问方式)/ Which / What:表‘如何’用 How。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp1','choice','{"stem":"\"___ makes the venom so deadly is not fully known.\"(名词从句作主语,‘什么…’,填连词)","options":["Which","Whether","That","What"],"answer_index":3,"stem_cn":"是什么让毒液如此致命,尚不完全清楚。","explanation_cn":"名词从句作全句开头,‘什么…’用 What(在从句中充当成分)。✓ What makes the venom so deadly is not known. ✗ That / Which / Whether:表‘什么’用 What。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp1','choice','{"stem":"\"___ Nature chose only snakes remains unexplained.\"(疑问词主语从句,‘为什么’,填连词)","options":["Why","Which","How","That"],"answer_index":0,"stem_cn":"大自然为何只选中了蛇,仍无解释。","explanation_cn":"疑问词从句作全句开头,‘为什么’用 Why。✓ Why Nature chose only snakes remains unexplained. ✗ That / Which / How:表‘为什么’用 Why。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp2','choice','{"stem":"\"Survival ___ hardly have forced the change on them.\"(‘不大可能曾…’,与 hardly have done 连用的情态词)","options":["need","can","must","dare"],"answer_index":1,"stem_cn":"生存竞争不大可能曾迫使它们发生这种改变。","explanation_cn":"情态词 + have + 过去分词表对过去推测;‘不大可能曾…’用 can hardly have done。✓ Survival can hardly have forced the change. ✗ must / need / dare:此处用 can。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp2','choice','{"stem":"\"The snakes must ___ developed the poison very slowly.\"(must + ___ + 过去分词,对过去的肯定推测,填中间的助动词)","options":["have","be","has","had"],"answer_index":0,"stem_cn":"蛇一定是极缓慢地才发展出这种毒的。","explanation_cn":"must + have + 过去分词,对过去的肯定推测;中间的助动词是 have。✓ must have developed the poison slowly. ✗ has / had / be:情态词后一律用 have。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp2','choice','{"stem":"\"Poison ___ not have appeared overnight; it took ages.\"(‘不可能曾…’,填与 not have 连用的情态词)","options":["should","could","would","may"],"answer_index":1,"stem_cn":"毒不可能一夜之间就出现,那用了千百万年。","explanation_cn":"情态词 + have + 过去分词;‘不可能曾…’用 could not have done(= couldn''t have)。✓ Poison could not have appeared overnight. ✗ would / should / may:表‘不可能曾’用 could not have。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp3','choice','{"stem":"\"It is often ___ that the nerve poison is more primitive.\"(‘据说、有人说’被动;say 的过去分词)","options":["to say","saying","said","say"],"answer_index":2,"stem_cn":"人们常说,神经毒是更原始的一种。","explanation_cn":"It is said that …,‘据说、有人说’;say 的过去分词 said。✓ It is often said that the nerve poison is primitive. ✗ saying / say / to say:被动用过去分词 said。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp3','choice','{"stem":"\"It ___ said that the blood poison came later.\"(It ___ said that…:‘据说’,填 be 动词)","options":["is","are","has","does"],"answer_index":0,"stem_cn":"据说血液毒是更新近的产物。","explanation_cn":"It ___ said that …:被动结构用 be 动词 is。✓ It is said that the blood poison came later. ✗ are / has / does:此结构用 is + said。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp3','choice','{"stem":"\"It is believed ___ venom evolved from ordinary saliva.\"(‘人们相信…’,填引出内容的连词)","options":["what","which","that","whether"],"answer_index":2,"stem_cn":"人们相信,毒液是由普通唾液演化而来。","explanation_cn":"It is believed + that 从句,‘人们相信…’;引出内容用 that。✓ It is believed that venom evolved from saliva. ✗ what / which / whether:引出陈述内容用 that。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp4','choice','{"stem":"\"Venom helps a hunter, ___ it may harm its own kind.\"(‘尽管、虽然’,填让步连词)","options":["once","though","unless","because"],"answer_index":1,"stem_cn":"毒液帮了捕食者,尽管它也可能伤到同类。","explanation_cn":"‘尽管、虽然’引导让步,用 though。✓ Venom helps a hunter, though it may harm its own kind. ✗ because / once / unless:表让步用 though。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp4','choice','{"stem":"\"___ two venomous hunters fight, the poison cuts both ways.\"(‘每当、无论何时’,填连词)","options":["Because","Unless","Although","Whenever"],"answer_index":3,"stem_cn":"每当两个带毒的猎手打斗,毒都是双刃的。","explanation_cn":"‘每当、无论何时’用 Whenever。✓ Whenever two venomous hunters fight, the poison cuts both ways. ✗ Because / Unless / Although:表‘每当’用 Whenever。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp4','choice','{"stem":"\"The poison is deadly, ___ it evolved for hunting, not for defense.\"(‘尽管、虽然’,填让步连词)","options":["once","because","though","unless"],"answer_index":2,"stem_cn":"这毒很致命,尽管它是为捕猎而非自卫演化来的。","explanation_cn":"‘尽管、虽然’引导让步,用 though。✓ The poison is deadly, though it evolved for hunting. ✗ because / once / unless:表让步用 though。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp5','choice','{"stem":"\"One venom is as ___ as the other, each in its way.\"(as + 形容词 + as,填形容词)","options":["deadly","deadliest","death","deadlier"],"answer_index":0,"stem_cn":"两种毒各有其道,一样致命。","explanation_cn":"as + 形容词 + as:同级比较;填形容词 deadly。✓ One venom is as deadly as the other. ✗ deadlier(比较级)/ deadliest(最高级)/ death(名词):as…as 中间用原级形容词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp5','choice','{"stem":"\"A cobra strikes as ___ as any viper does.\"(as + 副词 + as,填副词)","options":["quickest","quick","quickly","quicker"],"answer_index":2,"stem_cn":"眼镜蛇下口和任何蝰蛇一样快。","explanation_cn":"as + 副词 + as:修饰动词 strikes 用副词 quickly。✓ A cobra strikes as quickly as any viper. ✗ quick(形容词)/ quicker / quickest:此处用副词原级 quickly。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp5','choice','{"stem":"\"The bite works as ___ on a rat as on a mouse.\"(as + 副词 + as,填副词)","options":["more fast","fast","fastest","faster"],"answer_index":1,"stem_cn":"这一咬,对老鼠和对耗子一样快见效。","explanation_cn":"as + 副词 + as:fast 作副词原级。✓ works as fast on a rat as on a mouse. ✗ faster / fastest / more fast:as…as 中间用原级 fast。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp6','choice','{"stem":"\"The watery liquid in the mouth that begins digestion is ___.\"(“唾液”用哪个词)","options":["blood","oil","sweat","saliva"],"answer_index":3,"stem_cn":"口中开始消化的水样液体。","explanation_cn":"口中开始消化的水样液体是 saliva(唾液)。✓ the watery liquid in the mouth is saliva. ✗ blood 血;✗ sweat 汗;✗ oil 油——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp6','choice','{"stem":"\"An animal hunted and eaten by another is its ___.\"(“猎物”用哪个词)","options":["guide","prey","pet","hunter"],"answer_index":1,"stem_cn":"被别的动物捕食的动物。","explanation_cn":"被别的动物捕食的动物是 prey(猎物)。✓ an animal hunted by another is its prey. ✗ hunter 捕食者;✗ pet 宠物;✗ guide 向导——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',5,'am4_l20_gp6','choice','{"stem":"\"An animal that eats the flesh of others is a ___.\"(“食肉动物”用哪个词)","options":["plant","insect","carnivore","herbivore"],"answer_index":2,"stem_cn":"以别的动物的肉为食的动物。","explanation_cn":"以别的动物的肉为食的动物是 carnivore(食肉动物)。✓ an animal that eats flesh is a carnivore. ✗ herbivore 食草动物;✗ plant 植物;✗ insect 昆虫——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',6,NULL,'choice','{"stem":"venom 的意思是:","options":["毒液,毒","唾液","蜜","血"],"answer_index":0,"explanation_cn":"venom = 毒液、毒。✓ how snakes came to make venom."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',6,NULL,'choice','{"stem":"prey 的意思是:","options":["向导","猎物","捕食者","宠物"],"answer_index":1,"explanation_cn":"prey = 猎物。✓ catch and swallow their prey."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',6,NULL,'choice','{"stem":"defy 的意思是:","options":["欢迎","帮助","服从","使难以…,公然违抗"],"answer_index":3,"explanation_cn":"defy = 使难以…、公然违抗。✓ a poison that defies analysis."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',6,NULL,'choice','{"stem":"carnivore 的意思是:","options":["食肉动物","昆虫","食草动物","植物"],"answer_index":0,"explanation_cn":"carnivore = 食肉动物。✓ a help to almost any carnivore."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',6,NULL,'choice','{"stem":"saliva 的意思是:","options":["泪水","汗水","唾液","油脂"],"answer_index":2,"explanation_cn":"saliva = 唾液。✓ their saliva was turned into a poison."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',6,NULL,'choice','{"stem":"potency 的意思是:","options":["效力,威力","距离","重量","弱点"],"answer_index":0,"explanation_cn":"potency = 效力、威力。✓ each has its own potency."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',7,NULL,'cloze','{"stem":"第 1 空","context":"___1___ snakes came to make venom is a mystery. Their saliva was turned into a poison that ___2___ analysis. It is ___3___ that the nerve poison is older. The bite works fast, ___4___ the prey is a rat or a mouse.","blank_no":1,"options":["How","That","Which","What"],"answer_index":0,"explanation_cn":"疑问词从句作全句开头,‘…是如何’用 How。✓ How snakes came to make venom is a mystery."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',7,NULL,'cloze','{"stem":"第 2 空","context":"___1___ snakes came to make venom is a mystery. Their saliva was turned into a poison that ___2___ analysis. It is ___3___ that the nerve poison is older. The bite works fast, ___4___ the prey is a rat or a mouse.","blank_no":2,"options":["defies","defy","defying","defied"],"answer_index":0,"explanation_cn":"定语从句谓语随单数 a poison 用 defies;defy → defies。✓ a poison that defies analysis."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',7,NULL,'cloze','{"stem":"第 3 空","context":"___1___ snakes came to make venom is a mystery. Their saliva was turned into a poison that ___2___ analysis. It is ___3___ that the nerve poison is older. The bite works fast, ___4___ the prey is a rat or a mouse.","blank_no":3,"options":["said","saying","say","to say"],"answer_index":0,"explanation_cn":"It is said that …,‘据说’;say 的过去分词 said。✓ It is said that the nerve poison is older."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',7,NULL,'cloze','{"stem":"第 4 空","context":"___1___ snakes came to make venom is a mystery. Their saliva was turned into a poison that ___2___ analysis. It is ___3___ that the nerve poison is older. The bite works fast, ___4___ the prey is a rat or a mouse.","blank_no":4,"options":["whether","though","since","because"],"answer_index":0,"explanation_cn":"‘无论…还是…’用 whether。✓ works fast, whether the prey is a rat or a mouse."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',8,NULL,'choice','{"stem":"What are the two different ways in which snake poison acts?","options":["One burns, the other freezes","One acts on the nerves, the other on the blood","One helps, the other heals","One is fast, the other is fake"],"answer_index":1,"explanation_cn":"录音说蛇毒有两种不同作用方式:一种作用于神经,一种作用于血液。✓ nerves vs blood."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',8,NULL,'choice','{"stem":"Why does the passage call poison a ''luxury'' for a snake?","options":["It makes the snake beautiful","It is very expensive","It is rarely used","It lets the snake win its food with almost no effort"],"answer_index":3,"explanation_cn":"录音说毒对蛇是奢侈品,因为它让蛇几乎不费力就能获得食物。✓ win food with no effort."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',8,NULL,'choice','{"stem":"Which vertebrates did Nature give venom to?","options":["Only snakes and a single lizard","Every reptile","Cats and snakes","All carnivores"],"answer_index":0,"explanation_cn":"录音说大自然只把毒这件武器给了蛇和唯一一种蜥蜴。✓ snakes and one lizard."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',9,NULL,'choice','{"stem":"你想说\"蛇是如何造出毒液的,至今仍是个谜\"(how 引导、作全句开头的名词从句):","options":["That snakes came to make venom is still a mystery.","How snakes came to make venom are still a mystery.","How did snakes come to make venom is still a mystery.","How snakes came to make venom is still a mystery."],"answer_index":3,"explanation_cn":"how 引导的名词从句放在句首、充当全句开头;整句的动词用 is(单数)、从句内用陈述语序(不写 did snakes come)、不用 That。✓ How snakes came … is a mystery. 场合:说“…是如何…,是个谜”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',9,NULL,'choice','{"stem":"你想说\"据说神经毒是更原始的一种\"(It is said that):","options":["It is said that the nerve poison is the more primitive kind.","It is said the nerve poison is the more primitive kind that.","It is say that the nerve poison is the more primitive kind.","It said that the nerve poison is the more primitive kind."],"answer_index":0,"explanation_cn":"It is said that …:被动 is + said + that 从句;say 用过去分词 said、不能省 is、that 从句不后置。✓ It is said that … 场合:说“据说…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',9,NULL,'choice','{"stem":"你想说\"毒液帮了捕食者,尽管它也可能伤到同类\"(though 让步):","options":["Venom helps a hunter, though but it may harm its own kind.","Venom helps a hunter, though it may harm its own kind.","Venom helps a hunter, though it may harms its own kind.","Venom helps a hunter, despite it may harm its own kind."],"answer_index":1,"explanation_cn":"though‘尽管’引导让步,主句前不再加 but;may 后动词用原形 harm(不加 -s)、不用 despite 直接接句子。✓ …, though it may harm … 场合:说“…,尽管…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"venom 的意思是:","options":["唾液","血","毒液,毒","蜜"],"answer_index":2,"explanation_cn":"venom = 毒液、毒。✓ how snakes came to make venom."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"prey 的意思是:","options":["向导","猎物","宠物","捕食者"],"answer_index":1,"explanation_cn":"prey = 猎物。✓ catch and swallow their prey."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"\"___ snakes came to make venom is a mystery.\"(疑问词从句作全句开头)","options":["How","That","What","Which"],"answer_index":0,"stem_cn":"蛇是如何造出毒液的,是个谜。","explanation_cn":"疑问词从句作全句开头,‘…是如何’用 How。✓ How snakes came to make venom is a mystery. ✗ That / Which / What。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"\"It is ___ that the nerve poison is older.\"(‘据说’,say 的过去分词)","options":["say","said","saying","to say"],"answer_index":1,"stem_cn":"据说神经毒更古老。","explanation_cn":"It is said that …,‘据说’;say 的过去分词 said。✓ It is said that the nerve poison is older. ✗ saying / say / to say。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"\"come about\" 的意思是:","options":["回来","到来","发生、产生","转身"],"answer_index":2,"explanation_cn":"come about = 发生、产生。✓ how it came about is a mystery."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"\"act on\" 的意思是:","options":["作用于、对…起作用","拒绝","关闭","表演"],"answer_index":0,"explanation_cn":"act on = 作用于、对…起作用。✓ one poison acts on the nerves."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"According to the passage, why is snake poison a ''luxury'' rather than a necessity?","options":["All animals need poison","No snake can live without it","Only poison can kill rats","Non-poisonous snakes catch prey perfectly well without it"],"answer_index":3,"passage":"How snakes ever came to make venom is a real mystery. Over countless ages their saliva — an ordinary, mild digestive juice much like our own — was somehow turned into a poison so complex that it defies analysis even now. Survival can hardly have forced the change upon them, for thousands of harmless snakes still catch and swallow their prey perfectly well without a drop of venom. To a snake, poison is really a luxury: it lets the animal win its dinner with almost no effort — no more than a single bite. And why snakes alone? A cat, one would think, could use the gift just as much; it would be spared many a fierce struggle with a large rat. In truth venom would be a help to almost any carnivore, though it might prove a two-edged weapon whenever two such hunters fell to fighting. Yet, of all the vertebrates, unpredictable Nature handed this weapon to the snakes — and, oddly, to a single lizard — and to no one else. Snake venom does its deadly work in two quite different ways. Some snakes, among them the cobras, carry a poison that strikes at the nerves; others, such as the vipers, carry one that attacks the blood. The two are as unlike each other as two poisons can be, and each has its own potency. It is often said that the nerve poison is the older, more primitive kind, and the blood poison a newer product of an improved recipe. Whatever the truth of that, snakes did not develop their venom to use against people at all, but against small prey such as rats and mice — and on these little victims the poison acts almost at once.","explanation_cn":"课文说毒对蛇是奢侈而非必需,因为成千上万无毒的蛇不用毒液照样能捕食。✓ non-poisonous snakes catch prey without it."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"Which animals make the nerve poison and which make the blood poison?","options":["Both are made by cats","Only lizards make either","Cobras make the nerve poison; vipers make the blood poison","Vipers make both"],"answer_index":2,"passage":"How snakes ever came to make venom is a real mystery. Over countless ages their saliva — an ordinary, mild digestive juice much like our own — was somehow turned into a poison so complex that it defies analysis even now. Survival can hardly have forced the change upon them, for thousands of harmless snakes still catch and swallow their prey perfectly well without a drop of venom. To a snake, poison is really a luxury: it lets the animal win its dinner with almost no effort — no more than a single bite. And why snakes alone? A cat, one would think, could use the gift just as much; it would be spared many a fierce struggle with a large rat. In truth venom would be a help to almost any carnivore, though it might prove a two-edged weapon whenever two such hunters fell to fighting. Yet, of all the vertebrates, unpredictable Nature handed this weapon to the snakes — and, oddly, to a single lizard — and to no one else. Snake venom does its deadly work in two quite different ways. Some snakes, among them the cobras, carry a poison that strikes at the nerves; others, such as the vipers, carry one that attacks the blood. The two are as unlike each other as two poisons can be, and each has its own potency. It is often said that the nerve poison is the older, more primitive kind, and the blood poison a newer product of an improved recipe. Whatever the truth of that, snakes did not develop their venom to use against people at all, but against small prey such as rats and mice — and on these little victims the poison acts almost at once.","explanation_cn":"课文说眼镜蛇一类带的是攻击神经的毒,蝰蛇一类带的是攻击血液的毒。✓ cobras=nerve, vipers=blood."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"For use against what did snakes acquire their poison?","options":["Human beings","Other snakes only","Large cats","Small prey such as rats and mice"],"answer_index":3,"audio":"How snakes ever came to make venom is a real mystery. Over countless ages their saliva — an ordinary, mild digestive juice much like our own — was somehow turned into a poison so complex that it defies analysis even now. Survival can hardly have forced the change upon them, for thousands of harmless snakes still catch and swallow their prey perfectly well without a drop of venom. To a snake, poison is really a luxury: it lets the animal win its dinner with almost no effort — no more than a single bite. And why snakes alone? A cat, one would think, could use the gift just as much; it would be spared many a fierce struggle with a large rat. In truth venom would be a help to almost any carnivore, though it might prove a two-edged weapon whenever two such hunters fell to fighting. Yet, of all the vertebrates, unpredictable Nature handed this weapon to the snakes — and, oddly, to a single lizard — and to no one else. Snake venom does its deadly work in two quite different ways. Some snakes, among them the cobras, carry a poison that strikes at the nerves; others, such as the vipers, carry one that attacks the blood. The two are as unlike each other as two poisons can be, and each has its own potency. It is often said that the nerve poison is the older, more primitive kind, and the blood poison a newer product of an improved recipe. Whatever the truth of that, snakes did not develop their venom to use against people at all, but against small prey such as rats and mice — and on these little victims the poison acts almost at once.","explanation_cn":"课文说蛇发展出毒液不是为了对付人,而是为了对付老鼠、耗子之类的小猎物。✓ small prey, rats and mice."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l20',10,NULL,'choice','{"stem":"How quickly does viper poison act on small prey?","options":["Never","Only in winter","Almost at once","After several days"],"answer_index":2,"audio":"How snakes ever came to make venom is a real mystery. Over countless ages their saliva — an ordinary, mild digestive juice much like our own — was somehow turned into a poison so complex that it defies analysis even now. Survival can hardly have forced the change upon them, for thousands of harmless snakes still catch and swallow their prey perfectly well without a drop of venom. To a snake, poison is really a luxury: it lets the animal win its dinner with almost no effort — no more than a single bite. And why snakes alone? A cat, one would think, could use the gift just as much; it would be spared many a fierce struggle with a large rat. In truth venom would be a help to almost any carnivore, though it might prove a two-edged weapon whenever two such hunters fell to fighting. Yet, of all the vertebrates, unpredictable Nature handed this weapon to the snakes — and, oddly, to a single lizard — and to no one else. Snake venom does its deadly work in two quite different ways. Some snakes, among them the cobras, carry a poison that strikes at the nerves; others, such as the vipers, carry one that attacks the blood. The two are as unlike each other as two poisons can be, and each has its own potency. It is often said that the nerve poison is the older, more primitive kind, and the blood poison a newer product of an improved recipe. Whatever the truth of that, snakes did not develop their venom to use against people at all, but against small prey such as rats and mice — and on these little victims the poison acts almost at once.","explanation_cn":"课文说对这些小猎物,蝰蛇的毒几乎立刻见效。✓ almost at once."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l21',4,4,21,'The Star Who Made the Western','缔造西部片的明星','助动词 do/did/does 强调动词(myth and fact did meet)、过去分词作定语(a cowboy framed / the disinherited)、find/think it + 形容词 + to do、what 引导的名词从句、定语从句 who + 过去完成时(Men who had struggled…)(NCE4 无 KS 页,考点由课文结构自取;IP:源为卡尔·福尔曼《美德与快枪》,涉真实演员 William S. Hart/Gary Cooper/John Wayne,已按第四册铁律全换原创虚构明星 Wade Corliss、100% 原创行文,并避开原文‘攻击印第安人’等过时对立框架、聚焦好坏参半的局外人英雄与‘个体对抗逼近的文明’主题;无逐句改写;题材=早期西部片文化史·无害;美语化 movie/aluminum;第四册第21课)','在他那个年代,韦德·科利斯是早期西部片至高无上的明星——因为在他之后崛起的那些更圆熟、更出名的牛仔什么类型的片子都演,而科利斯只演西部片。整个默片年代,他无人能敌。正是科利斯最先塑造出西部片的基本套路,也正是科利斯设计了他在一部又一部影片里扮演的那个主角:好坏参半的人、无意间沦为逃犯的人、被冤枉陷害的老实牛仔、被恶毒流言弄得形迹可疑的警长——一句话,那个既与自己、又与身边严酷边疆为敌的孤独个体。与当时大多数片厂里的人不同,科利斯确实懂一点旧西部。他小时候就在那儿生活过,正是它已在消逝的那些年月;因此他的英雄牢牢扎根于他自己的记忆里,扎根于那片消失的边疆的历史与神话之中。尽管这个国家的过去,没有哪一段被比它更荒唐地浪漫化过,神话与事实却至少在一处确实相遇了:自由的个体,同一种步步进逼、要把一切规整起来的文明之间的冲突。那些一辈子都在同天气与荒野搏斗的人,被政客与银行家的新秩序弄得不知所措,又被栅栏、被成文的法律、被他们从未同意过的陌生禁忌层层围困。科利斯那好坏参半的人永远是个局外人,是被剥夺了产业的人之一;而如果一路上他偶尔越过了小镇画下的界线,早年的观众也觉得很容易理解、很容易原谅。他们坐在黑暗里想要的,是逃进一个更质朴的时代——而且更是想要一套可以依循的简单准则。我们至今仍想要它。','{"q":"Listen and answer — How did the star''s childhood prepare him for his acting role in Western films?","options":["He had lived in the old West as a boy, so his hero grew from real memories","He trained at a famous acting school","He read countless Western novels","He grew up far from any frontier"],"answer_index":0}'::jsonb,'{"title":"do/did 强调 / 过去分词作定语 / find it + 形容词 + to do / what 名词从句 / who + 过去完成","intro":"①助动词 do/did/does + 动词原形,强调该动作‘确实…’:myth and fact did meet。②过去分词作定语:a cowboy framed;the man disinherited。③find/think it + 形容词 + to do:found it easy to forgive。④what 引导名词从句:What they wanted was to escape。⑤定语从句 who + 过去完成:Men who had struggled … were bewildered。","table":{"headers":["用法","结构","例子"],"rows":[["do/did 强调","do/did/does + 动词原形","myth and fact did meet"],["过去分词作定语","名词 + 过去分词","a cowboy wrongly framed"],["find it + 形 + to do","find it + 形容词 + to do","found it easy to forgive"],["what 名词从句","What … + 谓语","What they wanted was to escape"],["who + 过去完成","who had + 过去分词","Men who had struggled …"]]},"specialRules":[{"rule":"do/did/does 放在动词原形前,可加强语气,表示‘确实、的确’:did meet、do love。","mark":"do/did + 动词原形"},{"rule":"find/think + it(形式宾语)+ 形容词 + to do:真正的对象是后面的不定式。","mark":"find it easy to do"},{"rule":"美式拼写/用词:movie(电影,英式 film)、aluminum(铝,英式 aluminium)。本课已按美语写。","mark":"movie / aluminum"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l21',1,NULL,'Wade Corliss was, in his day, the supreme star of the early Western — for while the smoother, more famous cowboys who came after him appeared in every kind of picture, Corliss appeared in nothing but Westerns. Through the silent years he stood unchallenged.','在他那个年代,韦德·科利斯是早期西部片至高无上的明星——因为在他之后崛起的那些更圆熟、更出名的牛仔什么类型的片子都演,而科利斯只演西部片。整个默片年代,他无人能敌。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l21',2,NULL,'It was Corliss who first shaped the basic formula of the Western film, and it was Corliss who designed the protagonist he played in picture after picture: the good-bad man, the accidental outlaw, the honest cowboy wrongly framed, the sheriff turned suspect by vicious gossip — in short, the lone individual at war with himself and with the harsh frontier around him.','正是科利斯最先塑造出西部片的基本套路,也正是科利斯设计了他在一部又一部影片里扮演的那个主角:好坏参半的人、无意间沦为逃犯的人、被冤枉陷害的老实牛仔、被恶毒流言弄得形迹可疑的警长——一句话,那个既与自己、又与身边严酷边疆为敌的孤独个体。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l21',3,NULL,'Unlike most of the studio men of his time, Corliss actually knew something of the old West. He had lived in it as a boy, in the very years when it was already fading, and so his hero was rooted firmly in his own memories and in the history and mythology of a vanished frontier.','与当时大多数片厂里的人不同,科利斯确实懂一点旧西部。他小时候就在那儿生活过,正是它已在消逝的那些年月;因此他的英雄牢牢扎根于他自己的记忆里,扎根于那片消失的边疆的历史与神话之中。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l21',4,NULL,'And although no chapter of the national past has been more absurdly romanticized, myth and fact did meet in at least one place: the clash between the free individual and an encroaching, tidy civilization. Men who had spent their lives struggling against the weather and the wilderness were bewildered by the new order of politicians and bankers, and hemmed in by fences, by written laws, by alien taboos they had never agreed to.','尽管这个国家的过去,没有哪一段被比它更荒唐地浪漫化过,神话与事实却至少在一处确实相遇了:自由的个体,同一种步步进逼、要把一切规整起来的文明之间的冲突。那些一辈子都在同天气与荒野搏斗的人,被政客与银行家的新秩序弄得不知所措,又被栅栏、被成文的法律、被他们从未同意过的陌生禁忌层层围困。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l21',5,NULL,'Corliss''s good-bad man was forever an outsider, one of the disinherited; and if, along the way, he sometimes crossed the line the town had drawn, the early audiences found it easy to understand and to forgive. What they wanted, sitting in the dark, was to escape into a plainer time — and, more than that, they wanted a simple code to live by. We want it still.','科利斯那好坏参半的人永远是个局外人,是被剥夺了产业的人之一;而如果一路上他偶尔越过了小镇画下的界线,早年的观众也觉得很容易理解、很容易原谅。他们坐在黑暗里想要的,是逃进一个更质朴的时代——而且更是想要一套可以依循的简单准则。我们至今仍想要它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
